    reg_base_value = old_reg_base_value;

  if (reg_base_value)
    reg_base_value->truncate (0);

  vec_safe_grow_cleared (reg_base_value, maxreg, true);

  new_reg_base_value = XNEWVEC (rtx, maxreg);
  reg_seen = sbitmap_alloc (maxreg);

  /* The basic idea is that each pass through this loop will use the

     The state of the arrays for the set chain in question does not matter
     since the program has undefined behavior.  */

  rpo = XNEWVEC (int, n_basic_blocks_for_fn (cfun));
  rpo_cnt = pre_and_rev_post_order_compute (NULL, rpo, false);

  pass = 0;
  do
    {
      /* Assume nothing will change this iteration of the loop.  */
      changed = false;

      /* We want to assign the same IDs each iteration of this loop, so
	 start counting from one each iteration of the loop.  */
      unique_id = 1;

      /* We're at the start of the function each iteration through the
	 loop, so we're copying arguments.  */
      copying_arguments = true;

      /* Wipe the potential alias information clean for this pass.  */
      memset (new_reg_base_value, 0, maxreg * sizeof (rtx));

      /* Wipe the reg_seen array clean.  */
      bitmap_clear (reg_seen);

      /* Initialize the alias information for this pass.  */
      for (i = 0; i < FIRST_PSEUDO_REGISTER; i++)
	if (static_reg_base_value[i]
	    /* Don't treat the hard frame pointer as special if we
	       eliminated the frame pointer to the stack pointer.  */
	    && !(i == HARD_FRAME_POINTER_REGNUM && frame_pointer_eliminated))
	  {
	    new_reg_base_value[i] = static_reg_base_value[i];
	    bitmap_set_bit (reg_seen, i);
	  }

	{
	  rtx note, set;

	  /* Treat the hard frame pointer as special unless we
	     eliminated the frame pointer to the stack pointer.  */
	  if (!frame_pointer_eliminated
	      && modified_in_p (hard_frame_pointer_rtx, insn))
	    continue;

	  /* If this insn has a noalias note, process it,  Otherwise,
	     scan for sets.  A simple set will have no side effects
	     which could change the base value of any other register.  */
	  if (GET_CODE (PATTERN (insn)) == SET
	      && REG_NOTES (insn) != 0
	      && find_reg_note (insn, REG_NOALIAS, NULL_RTX))
	    record_set (SET_DEST (PATTERN (insn)), NULL_RTX, NULL);
	  else
	    note_stores (insn, record_set, NULL);

	  set = single_set (insn);

	  if (set != 0
	      && REG_P (SET_DEST (set))
	      && REGNO (SET_DEST (set)) >= FIRST_PSEUDO_REGISTER)
	    {
	      unsigned int regno = REGNO (SET_DEST (set));
	      rtx src = SET_SRC (set);
	      rtx t;

	      note = find_reg_equal_equiv_note (insn);
	      if (note && REG_NOTE_KIND (note) == REG_EQUAL
		  && DF_REG_DEF_COUNT (regno) != 1)
		note = NULL_RTX;

	      poly_int64 offset;
	      if (note != NULL_RTX
		  && GET_CODE (XEXP (note, 0)) != EXPR_LIST
		  && ! rtx_varies_p (XEXP (note, 0), 1)
		  && ! reg_overlap_mentioned_p (SET_DEST (set),
						XEXP (note, 0)))
		{
		  set_reg_known_value (regno, XEXP (note, 0));
		  set_reg_known_equiv_p (regno,
					 REG_NOTE_KIND (note) == REG_EQUIV);
		}
	      else if (DF_REG_DEF_COUNT (regno) == 1
		       && GET_CODE (src) == PLUS
		       && REG_P (XEXP (src, 0))
		       && (t = get_reg_known_value (REGNO (XEXP (src, 0))))
		       && poly_int_rtx_p (XEXP (src, 1), &offset))
		{
		  t = plus_constant (GET_MODE (src), t, offset);
		  set_reg_known_value (regno, t);
		  set_reg_known_equiv_p (regno, false);
		}
	      else if (DF_REG_DEF_COUNT (regno) == 1
		       && ! rtx_varies_p (src, 1))
		{
		  set_reg_known_value (regno, src);
		  set_reg_known_equiv_p (regno, false);
		}
	    }
	}
      else if (NOTE_P (insn)
	       && NOTE_KIND (insn) == NOTE_INSN_FUNCTION_BEG)
